// The local-date epoch for daily numbering (day 0 = "No. 1"). Set to the real launch date at release, as on
// Petal Patch/Loop Break; a placeholder until then never breaks anything, it just back-dates the numbering.
export const EPOCH = { y: 2026, m: 9, d: 1 }; // month is 0-indexed: October = 9

// Local calendar day count since EPOCH. Uses the local Date constructor (never UTC): spec S2 "the daily date is
// local, never UTC".
export function daysSinceEpoch(y, m, d) {
  return Math.round((new Date(y, m - 1, d) - new Date(EPOCH.y, EPOCH.m, EPOCH.d)) / 86400000);
}

export function dailyIndex(y, m, d) {
  const days = daysSinceEpoch(y, m, d);
  return ((days % DAILY_SEEDS.length) + DAILY_SEEDS.length) % DAILY_SEEDS.length;
}

// Day number for the share line ("Captain Fold No. {N}"); day 0 (the epoch) is No. 1. Never negative: dates
// before the epoch still get a stable (if back-dated) number rather than a crash.
export function dailyNo(y, m, d) {
  return Math.max(0, daysSinceEpoch(y, m, d)) + 1;
}

export function courseById(id) {
  const c = PACK.find((p) => p.id === id);
  if (!c) throw new Error(`unknown course id "${id}"`);
  return { ...c, ...generateCourse(c.seed, c.d, { lengthM: c.lengthM }) };
}

export function dailyCourse(y, m, d) {
  const seed = DAILY_SEEDS[dailyIndex(y, m, d)];
  return { seed, d: 0.4, ...generateCourse(seed, 0.4) };
}
